{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")

    if "threshold" not in case:
        raise ValueError("Missing required field: threshold")
    if "calls" not in case:
        raise ValueError("Missing required field: calls")

    threshold = case["threshold"]
    calls = case["calls"]

    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")

    accepted_ids = []
    diagnostics = []

    for i, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError(f"call at index {i} must be a dict")

        required = ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable")
        for field in required:
            if field not in call:
                raise ValueError(f"Missing required field '{field}' in call at index {i}")

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(loss_without, (int, float)):
            raise ValueError(f"loss_without_call must be numeric for call {call_id}")
        if not isinstance(loss_with, (int, float)):
            raise ValueError(f"loss_with_call must be numeric for call {call_id}")
        if not isinstance(tokens, (int, float)) or tokens < 1:
            raise ValueError(f"prediction_tokens must be a number >= 1 for call {call_id}")
        if not isinstance(parseable, bool):
            raise ValueError(f"parseable must be a boolean for call {call_id}")

        # Stronger counterfactual: gain = loss without call minus loss with call
        gain = loss_without - loss_with

        # Normalize by prediction token count (at least 1, enforced above)
        normalized_gain = gain / tokens

        # Inclusive threshold: accept if parseable AND normalized_gain >= threshold
        accepted = parseable and normalized_gain >= threshold

        if accepted:
            accepted_ids.append(call_id)

        diagnostics.append({
            "call_id": call_id,
            "gain": round(gain, 8),
            "normalized_gain": round(normalized_gain, 8),
            "parseable": parseable,
            "accepted": accepted
        })

    return {
        "accepted_call_ids": accepted_ids,
        "total_accepted": len(accepted_ids),
        "total_calls": len(calls),
        "diagnostics": diagnostics
    }
